

#include <stddef.h>
#include <stdio.h>

int main(void) {
  volatile nullptr_t null_value   = nullptr;
  int               *null_pointer = nullptr;

  printf("%d %d\n", null_value == nullptr, null_pointer == nullptr);
  return 0;
}

// SLATE-FILECHECK-BEGIN x86_64-unknown-linux-gnu
// CHECK: {{^}}#![allow(non_camel_case_types)]
// CHECK-NEXT: #![no_main]
// CHECK-NEXT: unsafe extern "C" {
// CHECK-NEXT:     fn printf(__format: *const i8, ...) -> i32;
// CHECK-NEXT: }
// CHECK-NEXT: fn __slate_main() -> i32 {
// CHECK-NEXT:     let null_value: *mut () = std::ptr::null_mut::<()>();
// CHECK-NEXT:     let null_pointer: *mut i32 = std::ptr::null_mut::<i32>();
// CHECK-NEXT:     println!(
// CHECK-NEXT:         "{} {}", unsafe { std::ptr::read_volatile(std::ptr::addr_of!(null_value)) }
// CHECK-NEXT:         .is_null() as i32, null_pointer.is_null() as i32
// CHECK-NEXT:     );
// CHECK-NEXT:     0
// CHECK-NEXT: }
// CHECK-NEXT: #[unsafe(no_mangle)]
// CHECK-NEXT: unsafe extern "C-unwind" fn main(
// CHECK-NEXT:     argc: i32,
// CHECK-NEXT:     argv: *mut *mut std::ffi::c_char,
// CHECK-NEXT:     envp: *mut *mut std::ffi::c_char,
// CHECK-NEXT: ) -> i32 {
// CHECK-NEXT:     unsafe { __slate_main() }
// CHECK-NEXT: }
// CHECK-NOT: {{.}}
// SLATE-FILECHECK-END
